.ds-root {
  color-scheme: light;
  --bg: #f7f4ee;
  --raised: #fffdf9;
  --sunken: #efeae0;
  --line: #e3ddd1;
  --ink: #18181b;
  --ink-2: #3f3f46;
  --muted: #64645e;
  --forest: #26322b;
  --accent-ink: #2f5d40;
  --active-bg: #e8f0ea;
  --mari: #f2b33d;
  --focus: #2f5d40;
  --code-bg: #1b221e;
  --code-ink: #e7ece8;
  --button-bg: #26322b;
  --button-ink: #fffdf9;
  --top-h: 76px;
  --elevation: 0 12px 32px -8px rgb(38 30 18 / 18%);
  font-family: Inter, ui-sans-serif, system-ui, sans-serif;
  font-feature-settings: "cv11", "ss01";
  font-synthesis: none;}
.ds-root {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  -webkit-font-smoothing: antialiased;}
:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 4px;
}
.ds-primary {
  display: inline-flex;
  align-items: center;
  gap: 14px;
  padding: 11px 16px;
  border-radius: 8px;
  color: var(--button-ink);
  background: var(--button-bg);
  font-size: 14px;
  font-weight: 600;
  text-decoration: none;
}
.ds-app-link:hover,
.ds-primary:hover {
  opacity: 0.88;
}

