.ds-search-input {
  width: 100%;
  height: 42px;
  padding: 0 64px 0 40px;
  background: var(--raised);
  border: 1px solid var(--line);
  border-radius: 9px;
  color: var(--ink);
  font-size: 13px;
  caret-color: var(--accent-ink);
}
.ds-search-input::placeholder {
  color: var(--muted);
  opacity: 1;
}
.ds-search-input:focus {
  border-color: var(--focus);
}
.ds-search-input {font: inherit; font-size: 13px;}
.ds-visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}

